const La50FactoryPresetMeta& getFactoryPresetMeta(std::size_t index) noexcept
{
    return kPresetMeta[std::min(index, kFactoryPresetCount - 1u)];
}

const std::array<std::uint8_t, 448>& getFactoryPresetBytes448(std::size_t index) noexcept
{
    const std::size_t clamped = std::min(index, kFactoryPresetCount - 1u);
    return (clamped < 32u) ? kPresetBlobsA[clamped] : getFactoryPresetBytes448BankB(clamped - 32u);
}

void loadFactoryPresetPatch(std::size_t index, La50Patch& outPatch) noexcept
{
    const auto& bytes = getFactoryPresetBytes448(index);
    decodeD50Patch448(bytes.data(), outPatch);
}

